package com.nigson.experience.engagement;

import com.nigson.experience.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;

/** Experience-owned engagement commands. Commerce checks use a signed private port outside DB transactions. */
public final class EngagementService {
 @FunctionalInterface public interface PurchaseProof { boolean eligible(UUID party,UUID line,UUID product); }
 public interface MarketValidator { boolean active(UUID market); UUID resolve(String marketCode); }
 private final JdbcTemplate jdbc;private final PlatformStore store;private final AuditWriter audit;private final PurchaseProof purchases;private final MarketValidator markets;private final Clock clock;
 public EngagementService(JdbcTemplate jdbc,PlatformStore store,AuditWriter audit,PurchaseProof purchases,MarketValidator markets,Clock clock){this.jdbc=jdbc;this.store=store;this.audit=audit;this.purchases=purchases;this.markets=markets;this.clock=clock;}
 private static PrivateWorkload.Route route(String api){return PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)&&r.owner().equals("experience")).findFirst().orElseThrow(ActorAssertion::denied);}
 private ActorAssertion.Actor customer(PrivateWorkload.Proof p){var r=route("API-096");if(p==null||!r.equals(p.route())||!"nigson-commerce".equals(p.client())||p.actor()==null||!p.actor().roles().contains("CUSTOMER")||p.actor().organization()!=null||!p.actor().scopes().contains(r.scope()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return p.actor();}
 private ActorAssertion.Actor staff(PrivateWorkload.Proof p,String api,String role,String scope){var r=route(api);if(p==null||!r.equals(p.route())||!"nigson-commerce".equals(p.client())||p.actor()==null||p.actor().organization()!=null||!p.actor().roles().contains(role)||!p.actor().scopes().contains(scope))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return p.actor();}
 private static String subject(UUID party){return party.toString();}
 private UUID correlation(UUID c){return c==null?WireCorrelation.current():c;}
 private static java.sql.Timestamp ts(Instant i){return java.sql.Timestamp.from(i);}
 private static final class WireCorrelation {static UUID current(){var w=com.nigson.shared.observability.WireContext.current();return w==null?com.nigson.shared.observability.WireContext.correlation(null):w.correlationId;}}
 public EngagementValues.Review create(PrivateWorkload.Proof proof,EngagementValues.ReviewInput in,String key,UUID corr){var actor=customer(proof);if(in==null||!EngagementValues.KINDS.contains(in.kind()))throw ApiValues.invalid();ApiValues.idempotencyKey(key);var request=EventCodec.JSON.valueToTree(in);var replay=store.replayLocal(subject(actor.party()),"API-096",key,request);if(replay.isPresent())return EventCodec.JSON.treeToValue(replay.get().body(),EngagementValues.Review.class);if(in.kind().equals("PRODUCT")){if(purchases==null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);if(!purchases.eligible(actor.party(),in.orderLineId(),in.productId()))throw new Problem.Failure(ProblemCode.ENGAGEMENT_RULE_VIOLATION);}UUID id=EventCodec.uuid7(clock.instant());var response=store.executeLocal(subject(actor.party()),"API-096",key,request,db->{Instant now=clock.instant();int inserted=db.update("INSERT INTO experience.review(id,created_by,updated_by,product_id,order_line_id,party_id,kind,rating,title,body,state,verified_purchase) VALUES (?,?,?,?,?,?,?, ?,?,?, 'PENDING',?)",id,subject(actor.party()),subject(actor.party()),in.productId(),in.orderLineId(),actor.party(),in.kind(),in.rating(),in.title(),sanitize(in.body()),in.kind().equals("PRODUCT"));if(inserted!=1)throw new IllegalStateException("REVIEW_INSERT_FAILED");audit.append(subject(actor.party()),AuditValues.ActorKind.USER,AuditValues.Action.MODERATION,AuditValues.Resource.REVIEW,id,correlation(corr),AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("state","PENDING","kind",in.kind(),"verifiedPurchase",in.kind().equals("PRODUCT")),null);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(new EngagementValues.Review(id,"PENDING",in.rating(),in.kind().equals("PRODUCT"),0)),id);});return EventCodec.JSON.treeToValue(response.body(),EngagementValues.Review.class);}
 public EngagementValues.Page<EngagementValues.PublicReview> publicReviews(UUID product,String kind,int page,int size,String sort){EngagementValues.page(page,size);if(kind!=null&&!EngagementValues.KINDS.contains(kind)||!EngagementValues.PUBLIC_SORTS.contains(sort))throw ApiValues.invalid();String order=sort.equals("publishedAt,asc")?"updated_at ASC,id":"updated_at DESC,id";String base="FROM experience.review WHERE state='PUBLISHED'";String filter=(product==null?"":" AND product_id=?")+(kind==null?"":" AND kind=?");var args=new ArrayList<Object>();if(product!=null)args.add(product);if(kind!=null)args.add(kind);var pageArgs=new ArrayList<>(args);pageArgs.add(size);pageArgs.add((long)page*size);var rows=jdbc.query("SELECT id,rating,title,body,verified_purchase,updated_at "+base+filter+" ORDER BY "+order+" LIMIT ? OFFSET ?",(r,n)->new EngagementValues.PublicReview(r.getObject("id",UUID.class),"Nigson customer",r.getObject("rating")==null?null:((Number)r.getObject("rating")).intValue(),r.getString("title"),r.getString("body"),r.getBoolean("verified_purchase"),r.getTimestamp("updated_at").toInstant()),pageArgs.toArray());Long total=jdbc.queryForObject("SELECT count(*) "+base+filter,Long.class,args.toArray());return new EngagementValues.Page<>(rows,page,size,total==null?0:total,(int)Math.ceil((total==null?0:total)/(double)size));}
 public EngagementValues.Page<EngagementValues.AdminReview> queue(PrivateWorkload.Proof proof,String state,String kind,int page,int size,String sort){staff(proof,"API-176","CONTENT_PUBLISHER","reviews.read_WITH_SIGNED_ACTOR");EngagementValues.page(page,size);if(state!=null&&!EngagementValues.STATES.contains(state)||kind!=null&&!EngagementValues.KINDS.contains(kind)||!EngagementValues.SORTS.contains(sort))throw ApiValues.invalid();String order=sort.equals("createdAt,asc")?"created_at ASC,id":"created_at DESC,id";String filter=(state==null?"":" AND state=?")+(kind==null?"":" AND kind=?");var args=new ArrayList<>();if(state!=null)args.add(state);if(kind!=null)args.add(kind);var queryArgs=new ArrayList<>(args);queryArgs.add(size);queryArgs.add((long)page*size);var rows=jdbc.query("SELECT id,product_id,order_line_id,kind,title,body,rating,state,verified_purchase,version FROM experience.review"+filter+" ORDER BY "+order+" LIMIT ? OFFSET ?",(r,n)->new EngagementValues.AdminReview(r.getObject("id",UUID.class),r.getObject("product_id",UUID.class),r.getObject("order_line_id",UUID.class),r.getString("kind"),r.getString("title"),r.getString("body"),r.getObject("rating")==null?null:((Number)r.getObject("rating")).intValue(),r.getString("state"),r.getBoolean("verified_purchase"),r.getLong("version")),queryArgs.toArray());Long total=jdbc.queryForObject("SELECT count(*) FROM experience.review"+filter,Long.class,args.toArray());return new EngagementValues.Page<>(rows,page,size,total==null?0:total,(int)Math.ceil((total==null?0:total)/(double)size));}
 public EngagementValues.Review moderate(PrivateWorkload.Proof proof,UUID id,EngagementValues.Moderation m,long expected,String key,UUID corr){var actor=staff(proof,"API-098","CONTENT_PUBLISHER","reviews.moderate_WITH_SIGNED_ACTOR");if(id==null||m==null||!EngagementValues.DECISIONS.contains(m.decision())||expected<0)throw ApiValues.invalid();ApiValues.idempotencyKey(key);var request=EventCodec.JSON.valueToTree(Map.of("id",id,"decision",m.decision(),"reason",m.reason(),"version",expected));var saved=store.executeLocal(subject(actor.party()),"API-098:"+id,key,request,db->{var rows=db.queryForList("SELECT * FROM experience.review WHERE id=? FOR UPDATE",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();long current=((Number)row.get("version")).longValue();if(current!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);String before=(String)row.get("state"),after=switch(m.decision()){case "PUBLISH"->"PUBLISHED";case "REJECT"->"REJECTED";default->"WITHDRAWN";};boolean allowed=switch(m.decision()){case "PUBLISH"->before.equals("PENDING");case "REJECT"->before.equals("PENDING");default->before.equals("PUBLISHED");};if(!allowed)throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);long next=current+1;Instant now=clock.instant();db.update("UPDATE experience.review SET state=?,moderation_reason=?,version=?,updated_at=?,updated_by=? WHERE id=?",after,m.reason(),next,ts(now),subject(actor.party()),id);if(after.equals("PUBLISHED")){var event=new LinkedHashMap<String,Object>();event.put("event_id",EventCodec.uuid7(now));event.put("event_type","review.published.v1");event.put("schema_version",1);event.put("producer","experience");event.put("occurred_at",now.toString());event.put("aggregate_id",id);event.put("aggregate_version",next);event.put("organization_id",null);event.put("correlation_id",correlation(corr));event.put("traceparent",null);var payload=new LinkedHashMap<String,Object>();payload.put("review_id",id);payload.put("product_id",row.get("product_id"));event.put("payload",payload);store.append(EventCodec.JSON.writeValueAsString(event),subject(actor.party()));}audit.append(subject(actor.party()),AuditValues.ActorKind.USER,AuditValues.Action.MODERATION,AuditValues.Resource.REVIEW,id,correlation(corr),AuditValues.Reason.PUBLICATION_REVIEW,Map.of("state",before,"version",current),Map.of("state",after,"version",next,"reason",m.reason()),null);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new EngagementValues.Review(id,after,row.get("rating")==null?null:((Number)row.get("rating")).intValue(),(Boolean)row.get("verified_purchase"),next)),id);});return EventCodec.JSON.treeToValue(saved.body(),EngagementValues.Review.class);}
 public EngagementValues.Campaign createCampaign(PrivateWorkload.Proof proof,EngagementValues.CampaignInput in,String key,UUID corr){var actor=staff(proof,"API-108","SALES","campaigns.write_WITH_SIGNED_ACTOR");if(in==null||in.marketId()==null||in.startsAt()==null||in.endsAt()==null||!in.endsAt().isAfter(in.startsAt()))throw ApiValues.invalid();ApiValues.idempotencyKey(key);var request=EventCodec.JSON.valueToTree(in);var replay=store.replayLocal(subject(actor.party()),"API-108",key,request);if(replay.isPresent())return EventCodec.JSON.treeToValue(replay.get().body(),EngagementValues.Campaign.class);if(in.commercialRuleId()!=null)throw new Problem.Failure(ProblemCode.ENGAGEMENT_RULE_VIOLATION);if(markets==null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);if(!markets.active(in.marketId()))throw new Problem.Failure(ProblemCode.ENGAGEMENT_RULE_VIOLATION);UUID id=EventCodec.uuid7(clock.instant());var saved=store.executeLocal(subject(actor.party()),"API-108",key,request,db->{Instant now=clock.instant();db.update("INSERT INTO experience.campaign(id,created_by,updated_by,code,title,market_id,commercial_rule_id,display_config,starts_at,ends_at,published) VALUES (?,?,?,?,?,?,?,?::jsonb,?,?,?)",id,subject(actor.party()),subject(actor.party()),in.code(),in.title(),in.marketId(),in.commercialRuleId(),EventCodec.JSON.writeValueAsString(in.displayConfig()),ts(in.startsAt()),ts(in.endsAt()),in.published());audit.append(subject(actor.party()),AuditValues.ActorKind.USER,AuditValues.Action.PROMOTION_CONFIG,AuditValues.Resource.PROMOTION,id,correlation(corr),AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("published",in.published(),"displayOnly",true,"marketId",in.marketId()),null);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(new EngagementValues.Campaign(id,in.code(),in.title(),in.marketId(),in.commercialRuleId(),in.displayConfig(),in.startsAt(),in.endsAt(),in.published(),0)),id);});return EventCodec.JSON.treeToValue(saved.body(),EngagementValues.Campaign.class);}
 public List<EngagementValues.PublicCampaign> publicCampaigns(String marketCode){if(marketCode==null||!marketCode.matches("[A-Z0-9][A-Z0-9_-]{1,39}")||markets==null)throw ApiValues.invalid();UUID market=markets.resolve(marketCode);if(market==null)throw new Problem.Failure(ProblemCode.NOT_FOUND);Instant now=clock.instant();return jdbc.query("SELECT id,code,title,display_config,starts_at,ends_at FROM experience.campaign WHERE market_id=? AND published=true AND starts_at<=? AND ends_at>? ORDER BY starts_at,id LIMIT 100",(r,n)->new EngagementValues.PublicCampaign(r.getObject("id",UUID.class),r.getString("code"),r.getString("title"),EventCodec.JSON.readTree(r.getString("display_config")),r.getTimestamp("starts_at").toInstant(),r.getTimestamp("ends_at").toInstant()),market,ts(now),ts(now));}
 private static String sanitize(String s){return s.codePoints().filter(c->!Character.isISOControl(c)||c=='\n'||c=='\t').filter(c->Character.getType(c)!=Character.FORMAT).collect(StringBuilder::new,StringBuilder::appendCodePoint,StringBuilder::append).toString();}
}
